def tr(name):
    name=name.replace("2břit","2-britý").replace("se světelnými efekty","so svetelnými efektmi").replace("navrací vlasům lesk","vracia vlasom lesk")
    s=name.replace("&#039;","'").replace("&amp;","&")
    # phrases, longest first
    for k in sorted(PH,key=len,reverse=True):
        s=re.sub(r"(?<![\w])"+re.escape(k)+r"(?![\w])",lambda m:cap(m.group(0),PH[k]),s,flags=re.I)
    def one(m):
        t=m.group(0);tl=t.lower()
        if tl=='pro' and t!='pro': return t
        if tl in W: return cap(t,W[tl])
        return t
    s=re.sub(r"[^\W\d_]+",one,s)
    s=re.sub(r"(\d)\s*(ML|ml)\b",r"\1 ml",s); s=re.sub(r"(\d)\s*(?:ks|KS)\b",r"\1 ks",s); s=re.sub(r"(\d)\s*(g|G)\b",r"\1 g",s)
    return s
def czech_left(s):
    return [t for t in re.findall(r"[^\W\d_]+",s) if re.search(r"[ěřůĚŘŮ]",t)]
if __name__=="__main__":
    bad=json.load(open("ops/sk-work/new-badnames.json"))
    left=[];
    for c,n,_ in bad:
        sk=tr(n); cl=czech_left(sk)
        if cl: left.append((c,n,sk,cl))
    print(len(bad),"unresolved",len(left))
    for c,n,sk,cl in left[:60]: print(c,n,"->",sk,cl)
